erved_verdict": "descriptive", "observed_failure_type": "E_unclear", "observed_notes": "NOT_RECORDED", "auto_confidence": "medium (0.65)"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPS-049"}, {"rel": "auto_addresses_question", "node": "RQC:RQC-005"}]}, {"id": "FAM:SF-CHT-025", "label": "Study family SF-CHT-025: Play-type labeling audit: OTHER/DRIVE foul leakage", "score": 0.932, "reached_via": ["request matches the question or hypothesis of FAM:SF-CHT-025 (0.81)", "request matches VAR:PPP_points_per_possession (0.80); FAM:SF-CHT-025 auto_measures VAR:PPP_points_per_possession"], "attributes": {"observed_research_question": "Play-type labeling audit: OTHER/DRIVE foul leakage", "auto_outcome_status": "artifact", "observed_hypothesis": "Play-type PPP differences are real efficiency, not labeling/foul artifacts.", "observed_result": "OTHER: 36% end in fouls, PPP inflated (FOUL_BUCKET). DRIVE: 12pp below foul benchmark (FOUL_LEAK). PNR shows 22% foul rate. Only 335 of 50,668 possessions (0.7%) map to a real play type via initiation_type.", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "OTHER PPP inflated by 36% foul endings; DRIVE 12pp below foul benchmark; initiation_type maps 0.7%.", "observed_sample_and_power": "50,668 possessions in the initiation_type check", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Per-PT diagnostic of foul-ending share vs PPP; initiation_type mapping.", "observed_verdict": "artifact_found"}, "relationships": []}, {"id": "FAM:SF-APPA-058", "label": "Study family SF-APPA-058: Season stability of top suppressors and negative teammate pairs", "score": 0.876, "reached_via": ["request matches RQC:RQC-053 (0.74); FAM:SF-APPA-058 auto_addresses_question RQC:RQC-053", "FAM:SF-APPA-050 auto_related_family (record_link_extends) FAM:SF-APPA-058"], "attributes": {"observed_research_question": "Season stability of top suppressors and negative teammate pairs", "auto_outcome_status": "rejected", "observed_hypothesis": "Each star's top sequential suppressor is stable across seasons, and some teammate X->Y sequences have large negative premiums.", "observed_result": "2/30 (7%) stable (>=75% same top suppressor): D. Mitchell PUTBACK 75%, L. James POST_UP 75%. Negative: J. Tatum->K. Porzingis DRIVE->SPOT_UP -0.444 n=31; Giannis->Lillard DRIVE->PNR -0.263 n=31; J. Brown->J. Tatum SPOT_U [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "Only 2/30 stars meet the 75% same-top-suppressor stability rule.", "observed_sample_and_power": "30 stars x 4 seasons; min n=20/cell", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "null"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-CHT-009", "label": "Study family SF-CHT-009: Superstar suppression by lineup and forced play type", "score": 0.727, "reached_via": ["request matches RQC:RQC-098 (0.76); FAM:SF-CHT-009 auto_addresses_question RQC:RQC-098", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.76); FAM:SF-CHT-009 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Superstar suppression by lineup and forced play type", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Named star initiators have identifiable lineup and forced-play-type suppressors in the possession graph.", "observed_result": "Jokic vs MIN lineup PPP 0.814, -0.385 (n=59); Curry vs HOU 0.851, -0.358 (n=47); Doncic vs LAC 0.733, -0.396 (n=30); Giannis forced PULL_UP 0.848, -0.540 vs preferred DRIVE (largest gap).", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No placebo or matching; later sequence work treated similar star-chain gaps as artifacts.", "observed_sample_and_power": "n>=30 for lineup cells cited", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Jokic/Curry/Doncic/Giannis; min-15 gate on 8 play types; opposing DEFENSE_LINEUP ~84% coverage; 272-row CSV."}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:PLACEBO_DEPENDENCE"}]}, {"id": "FAM:SF-APPS-078", "label": "Study family SF-APPS-078: Channel 2: possession ending state vs next 90-180s volume/points", "score": 0.67, "reached_via": ["FAM:SF-APPS-075 auto_related_family (record_link_related_to) FAM:SF-APPS-078", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.76); FAM:SF-APPS-078 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Channel 2: possession ending state vs next 90-180s volume/points", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "A possession's ending state changes opponent points/possessions in the next 90-180s beyond ~0.01-0.02 PPP boundary drift.", "observed_result": "90s vs MADE_DEAD: TURNOVER_LIVE dOppPts=+0.510 dNetPts=-0.306 (dOppPPP=+0.055, dOppPoss=+0.298); MISSED_DEAD dNetPts=-0.112; PUTBACK dNetPts=+0.078. Volume (dOppPoss), not PPP, carries most of the live-TO cost.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No inferential tests in the core table; live TO raising opponent possession count is largely definitional (steal starts a break).", "observed_sample_and_power": "n=911968; MADE_DEAD n=354564", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "descriptive"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPS-075"}]}], "n_results": 10}

